import sys;from viet_chung import xuat
# Thủy mặc tập 8: Chi Lăng, Xương Giang 1427 (mã tm8), bản 2
S=[
(1,"Mười vạn quân giặc đang tràn qua cửa ải, đuổi theo một toán quân nhỏ cứ đánh vài trận rồi lại lùi."),
(1,"Nhưng toán quân ấy không phải đang thua. Nó đang kéo vị tướng chỉ huy mười vạn quân kia vào một thung lũng hẹp."),
(1,"Thung lũng ấy là ải Chi Lăng. Vị tướng ấy là Liễu Thăng của nhà Minh, và ông đã phải trả giá bằng chính mạng mình ở núi Mã Yên gần đó."),
(1,"Một cái chết kéo theo ba lần sụp đổ: ở Chi Lăng, ở Xương Giang, và ở một doanh trại cách đó rất xa. Chúng đã sụp đổ thế nào?"),
(2,"Cuối năm một nghìn bốn trăm hai mươi sáu, tướng nhà Minh là Vương Thông bị nghĩa quân Lam Sơn vây chặt ở thành Đông Quan, tức Thăng Long."),
(2,"Vì thế, nhà Minh sai hai đạo quân sang cứu. Liễu Thăng đem mười vạn quân và hai vạn ngựa, theo đường Lạng Sơn kéo xuống."),
(2,"Cùng lúc ấy, tướng Mộc Thạnh đem năm vạn quân theo đường Vân Nam tiến sang. Hai đạo quân được giao cùng tới Đông Quan để phá vòng vây."),
(2,"Các tướng Lam Sơn muốn đánh ngay thành Đông Quan trước khi viện binh tới. Lê Lợi không chịu, vì đánh vào thành vững là cách kém nhất."),
(2,"Vì thế, ông để quân giữ sức, chờ đánh quân cứu viện ngoài đồng trống, và nhắm trước vào đạo quân lớn nhất của Liễu Thăng."),
(3,"Rồi ở cửa ải đầu tiên, tướng Trần Lựu đánh vài trận rồi lui dần, lui mãi về tận ải Chi Lăng."),
(3,"Ải Chi Lăng là một thung lũng hẹp, hai bên là núi đá, giữa là đường đi và đầm lầy. Nghĩa quân đã phục sẵn ở đó."),
(3,"Thắng liền mấy trận đầu, Liễu Thăng cứ thế đuổi theo. Thấy quân Lam Sơn chỉ lui, ông càng đuổi gấp hơn."),
(3,"Đến ngày hai mươi tháng Chín, ông chỉ đem hơn một trăm kỵ binh vượt lên trước, tới chân núi Mã Yên."),
(3,"Đúng lúc ấy, phục binh từ bốn phía đổ ra. Liễu Thăng bị giết ngay tại chỗ, trong khi đại quân của ông còn ở phía sau."),
(3,"Đó là lần sụp đổ thứ nhất: mười vạn quân mất chủ tướng ngay ở cửa ngõ vào nước ta."),
(4,"Mất chủ tướng, đạo quân ấy vẫn còn rất đông, và vẫn cố tiến về phía Đông Quan. Nhưng đi đến đâu, họ cũng bị chặn đánh."),
(4,"Chỉ năm ngày sau, tướng Lương Minh tử trận. Thêm ba ngày nữa, Lý Khánh, một viên quan lớn theo đạo quân, cũng tự tử."),
(4,"Còn hai tướng Thôi Tụ và Hoàng Phúc dẫn quân tới thành Xương Giang, mong có chỗ dựa."),
(4,"Nhưng tới nơi, họ mới biết thành Xương Giang đã bị nghĩa quân hạ từ trước. Không có thành để dựa, quân nhà Minh đành đóng trại giữa cánh đồng trống."),
(4,"Nghĩa quân chưa đánh ngay. Họ vây kín bốn mặt, cắt đường lấy lương, để đạo quân ấy đói dần giữa đồng."),
(4,"Đến tháng Mười, nghĩa quân mới đánh vào. Doanh trại vỡ tan, Thôi Tụ và Hoàng Phúc đều bị bắt sống."),
(4,"Xương Giang là lần sụp đổ thứ hai. Đạo quân mười vạn người của Liễu Thăng coi như không còn."),
(5,"Lúc ấy Mộc Thạnh đã vào tới vùng Lê Hoa, gần biên giới Vân Nam. Năm vạn quân của ông vẫn chưa đánh trận lớn nào."),
(5,"Theo sử cũ, Lê Lợi sai đem những thư từ và con dấu lấy được của Liễu Thăng đến cho Mộc Thạnh xem."),
(5,"Thấy thư và dấu của Liễu Thăng nằm trong tay đối phương, Mộc Thạnh biết đạo quân kia đã tan, liền bỏ chạy về nước."),
(5,"Nghĩa quân đuổi theo và đánh tan quân của Mộc Thạnh trên đường rút. Chính ông chỉ kịp chạy thoát thân, và đó là lần sụp đổ thứ ba."),
(6,"Hết hy vọng cứu viện, Vương Thông trong thành Đông Quan đành xin thôi đánh để được rút về nước."),
(6,"Tháng Chạp năm ấy, hai bên làm lễ thề ở phía nam thành Đông Quan. Lê Lợi cho quân nhà Minh về nước, còn cấp cả thuyền và ngựa."),
(6,"Một toán quân cứ đánh rồi lùi đã kéo Liễu Thăng vào Chi Lăng, rồi kéo sập cả hai đạo quân cứu viện. Cảm ơn bạn đã lắng nghe câu chuyện này."),
]
xuat(S,'tm8',183001)
